begin;
select plan(36);

select has_table('public', 'contacts', 'contacts table exists');
select has_table('public', 'companies', 'companies table exists');
select has_table('public', 'scheduled_jobs', 'scheduled job table exists');
select has_table('public', 'sequence_enrollments', 'sequence enrollment table exists');
select has_table('public', 'mailbox_accounts', 'mailbox account table exists');
select has_table('public', 'campaigns', 'campaign table exists');
select has_table('public', 'contact_lists', 'contact list table exists');
select has_constraint('public', 'contacts', 'contacts_company_same_org_fk', 'contact company relation is tenant scoped');
select has_constraint('public', 'deals', 'deals_stage_same_pipeline_fk', 'deal stage belongs to selected pipeline');
select has_constraint('public', 'send_attempts', 'send_attempt_campaign_same_org_fk', 'campaign sends are tenant scoped');
select ok((select relrowsecurity from pg_class where oid = 'public.email_messages'::regclass), 'email messages have row-level security enabled');
select ok(not has_table_privilege('authenticated', 'public.scheduled_jobs', 'select'), 'scheduled jobs are not readable from browser role');
select ok(not has_table_privilege('authenticated', 'public.mailbox_credential_refs', 'select'), 'mailbox secret references are not readable from browser role');
select has_trigger('public', 'contacts', 'contacts_record_activity_after_insert', 'contact inserts write CRM timeline events');
select has_trigger('public', 'contacts', 'contacts_record_activity_after_update', 'contact updates write CRM timeline events');
select ok((select prosecdef from pg_proc where oid = 'public.record_contact_activity()'::regprocedure), 'contact activity writer runs as a trusted trigger function');
select ok(not has_table_privilege('authenticated', 'public.activity_events', 'insert'), 'browser role cannot forge CRM timeline events');
select has_column('public', 'profiles', 'email', 'profile email supports administrative roster display');
select ok(not has_function_privilege('authenticated', 'public.admin_add_org_member(uuid,uuid,uuid,public.member_role)', 'execute'), 'browser role cannot bypass the team authorization endpoint');
select ok(has_function_privilege('service_role', 'public.admin_add_org_member(uuid,uuid,uuid,public.member_role)', 'execute'), 'trusted server can use transactional member assignment');
select ok(not has_table_privilege('authenticated', 'public.team_invite_rate_limits', 'select'), 'browser role cannot inspect invitation rate counters');
select ok(not has_function_privilege('authenticated', 'public.admin_reserve_team_invite(uuid,uuid)', 'execute'), 'browser role cannot reserve administrative invites');
select ok(has_function_privilege('service_role', 'public.admin_reserve_team_invite(uuid,uuid)', 'execute'), 'trusted server can reserve rate-limited invitations');
select has_trigger('public', 'deals', 'deals_record_created_activity', 'deal inserts record initial stage history and CRM activity');
select ok((select prosecdef from pg_proc where oid = 'public.record_deal_created()'::regprocedure), 'deal activity writer runs as a trusted trigger function');
select has_column('public', 'deals', 'next_action', 'deal next action is stored as structured data');
select has_column('public', 'deals', 'expected_close_on', 'deal expected close date is stored as structured data');
select has_table('public', 'mailbox_connection_rate_limits', 'mailbox connection attempts have a durable rate-limit table');
select has_column('public', 'mailbox_credential_refs', 'credential_ciphertext', 'encrypted mailbox credentials have a dedicated server-only field');
select ok(not has_table_privilege('authenticated', 'public.mailbox_credential_refs', 'select'), 'browser role cannot read encrypted mailbox credentials');
select ok(not has_function_privilege('authenticated', 'public.reserve_mailbox_connection_test(uuid,uuid)', 'execute'), 'browser role cannot reserve mailbox connection attempts');
select ok(has_function_privilege('service_role', 'public.reserve_mailbox_connection_test(uuid,uuid)', 'execute'), 'trusted mailbox service can reserve connection tests');
select ok(not has_function_privilege('authenticated', 'public.create_mailbox_account(uuid,uuid,text,text,integer,text,text,text,text)', 'execute'), 'browser role cannot create mailbox accounts through the trusted RPC');
select ok(has_function_privilege('service_role', 'public.create_mailbox_account(uuid,uuid,text,text,integer,text,text,text,text)', 'execute'), 'trusted mailbox service can persist verified mailbox accounts');
select ok(not has_function_privilege('authenticated', 'public.persist_inbound_message(uuid,uuid,text,text,text,bigint,text,text,text,text,text[],text,text,text,text,timestamptz,jsonb,jsonb,jsonb)', 'execute'), 'browser role cannot persist synchronized messages');
select ok(has_function_privilege('service_role', 'public.persist_inbound_message(uuid,uuid,text,text,text,bigint,text,text,text,text,text[],text,text,text,text,timestamptz,jsonb,jsonb,jsonb)', 'execute'), 'trusted mailbox service can persist synchronized messages atomically');

select * from finish();
rollback;
